#' Annotate assay data with chemical identities
#'
#' Integrates experimental assay data with annotation files to assign
#' chemical identities to individual wells. Annotation tables are assumed
#' to be preloaded in the R environment.
#'
#' @param data A list object containing a data frame element named
#'   \code{data}, typically generated by \code{read_folder()}. The data frame
#'   must include the columns \code{"Plate Type"} and \code{"Well"}.
#' @param annotation A data frame or a list of data frames containing annotation
#'   metadata. Each data frame must include the columns \code{"Plate Type"},
#'   \code{"Well"}, and \code{"Chemical"}.
#' @param control_map Optional named list specifying control classifications.
#'   Each name defines a control category, and each element is a character vector
#'   of chemical names assigned to that category. Defaults include
#'   \code{negative} and \code{positive} controls.
#'
#' @details
#' The function performs the following operations:
#' \enumerate{
#'   \item Accepts one or multiple annotation data frames.
#'   \item Combines annotation tables into a unified data frame and removes duplicates.
#'   \item Merges annotation metadata with the experimental dataset based on
#'         \code{"Plate Type"} and \code{"Well"}.
#'   \item Optionally assigns control categories based on chemical identity using
#'         \code{control_map}.
#' }
#'
#' Column name matching is case-sensitive; ensure consistent naming across inputs.
#'
#' @return The input \code{data} object with an updated \code{data} element,
#'   containing merged annotation columns and, if applicable, an additional
#'   \code{control} column indicating control classification.
#'
#' @importFrom dplyr bind_rows distinct left_join mutate case_when select
#' @importFrom purrr imap map_lgl
#' @importFrom rlang expr
#'
#' @examples
#' data("processed_data")
#' data("PM_M01_M02")
#' processed_data <- annotate_chemical(processed_data, annotation = PM_M01_M02)
#' head(processed_data$data)
#' 
#' @export
annotate_chemical <- function(
    data,
    annotation,
    control_map = list( negative = c("Negative Control", "No Chemical"), 
                        positive = c("a-D-Glucose", "D-(+)-Glucose") ) ) {
  
  # ---- Validate input structure ----
  if (!("data" %in% names(data))) {
    stop("'data' must contain a 'data' element.")
  }
  
  data_df <- data$data
  
  if (!is.data.frame(data_df)) {
    stop("'data$data' must be a data.frame.")
  }
  
  # ---- Handle annotation input ----
  if (is.data.frame(annotation)) {
    annotations_list <- list(annotation)
  } else if (is.list(annotation) && all(purrr::map_lgl(annotation, is.data.frame))) {
    annotations_list <- annotation
  } else {
    stop("'annotation' must be a data.frame or a list of data.frames.")
  }
  
  # ---- Combine annotations ----
  annotations <- dplyr::bind_rows(annotations_list) %>%
    dplyr::distinct()
  
  # ---- Check if annotations are empty ----
  if (nrow(annotations) == 0) {
    warning("No annotation data was provided or all annotation rows were duplicates. ",
            "No chemical identities will be assigned to wells.")
  }
  
  # ---- Required columns ----
  required_cols <- c("Plate Type", "Well")
  
  if (!all(required_cols %in% names(annotations))) {
    stop(
      "Annotation must contain columns: ",
      paste(required_cols, collapse = ", "),
      "\nFound: ",
      paste(names(annotations), collapse = ", ")
    )
  }
  
  # ---- Merge ----
  data_df <- dplyr::left_join(
    data_df,
    dplyr::select(annotations, "Plate Type", "Well", "Chemical"),
    by = c("Plate Type", "Well")
  )
  
  
  # ---- Control classification ----
  if (!is.null(control_map) && "Chemical" %in% names(data_df)) {
    
    # ---- Warn if any wells have NA in Chemical after merge ----
    n_annotated <- sum(!is.na(data_df$Chemical))
    n_total <- nrow(data_df)
    
    if (n_annotated == 0) {
      warning("No chemical annotations were successfully merged. ",
              "All wells have NA in 'Chemical'. Check that 'Plate Type' and 'Well' ",
              "match between the data and annotation tables.")
    } else if (n_annotated < n_total) {
      # Find the missing wells (those with NA in Chemical)
      missing_wells <- data_df %>%
        dplyr::filter(is.na(Chemical)) %>%
        dplyr::select("Plate Type", "Well") %>%
        dplyr::distinct() %>%
        dplyr::arrange("Plate Type", "Well") %>%
        dplyr::pull(paste0("Plate Type", "_", "Well"))
      
      # Format the list nicely
      if (length(missing_wells) <= 10) {
        warning("Only ", n_annotated, " out of ", n_total, " wells were annotated. ",
                "The following ", length(missing_wells), " wells were not matched: ",
                paste(missing_wells, collapse = ", "), ".",
                "This may indicate missing or mismatched 'Plate Type' or 'Well' values.")
      } else {
        warning("Only ", n_annotated, " out of ", n_total, " wells were annotated. ",
                "The following ", length(missing_wells), " wells were not matched: ",
                paste(head(missing_wells, 5), collapse = ", "), "... (and ", 
                length(missing_wells) - 5, " more).",
                "Check 'Plate Type' and 'Well' values for mismatches.")
      }
    }
    
    
    data_df <- dplyr::mutate(
      data_df,
      control = dplyr::case_when(
        !!!purrr::imap(control_map, ~ rlang::expr(Chemical %in% !!.x ~ !!.y)),
        TRUE ~ NA_character_
      )
    )
  }
  
  # ---- Return ----
  data$data <- data_df
  return(data)
}